Here’s a minimal Flask login using **Flask-Login**, SQLite, and Werkzeug password hashing. It uses Flask’s signed session cookie—no password or login token is stored in the cookie.

```python
import os
import sqlite3

from flask import Flask, g, request, jsonify
from flask_login import (
    LoginManager, UserMixin, current_user, login_required,
    login_user, logout_user,
)
from werkzeug.security import check_password_hash

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["FLASK_SECRET_KEY"],  # Set a long, random secret
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SECURE=True,  # Requires HTTPS; disable only for local HTTP development
    SESSION_COOKIE_SAMESITE="Lax",
)

DATABASE = "app.sqlite3"

login_manager = LoginManager(app)


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(_error):
    db = g.pop("db", None)
    if db is not None:
        db.close()


class User(UserMixin):
    def __init__(self, user_id, username, password_hash):
        self.id = str(user_id)
        self.username = username
        self.password_hash = password_hash


def get_user_by_id(user_id):
    row = get_db().execute(
        "SELECT id, username, password_hash FROM users WHERE id = ?",
        (user_id,),
    ).fetchone()
    return User(row["id"], row["username"], row["password_hash"]) if row else None


@login_manager.user_loader
def load_user(user_id):
    return get_user_by_id(user_id)


@app.post("/login")
def login():
    data = request.get_json(silent=True) or request.form
    username = data.get("username", "").strip()
    password = data.get("password", "")

    if not username or not password:
        return jsonify(error="Username and password are required"), 400

    row = get_db().execute(
        "SELECT id, username, password_hash FROM users WHERE username = ?",
        (username,),
    ).fetchone()

    # Use the same response for unknown users and wrong passwords.
    if row is None or not check_password_hash(row["password_hash"], password):
        return jsonify(error="Invalid username or password"), 401

    user = User(row["id"], row["username"], row["password_hash"])
    login_user(user)
    return jsonify(message="Logged in")


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return jsonify(message="Logged out")


@app.get("/protected")
@login_required
def protected():
    return jsonify(message=f"Hello, {current_user.username}")
```

Your `users` table should contain a **password hash**, not a plaintext password:

```sql
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL
);
```

When registering a user, hash the password with `werkzeug.security.generate_password_hash()` before inserting it. Keep `FLASK_SECRET_KEY` out of your source code, use HTTPS in production, and add CSRF protection if these endpoints are used by browser forms.

Below is a minimal **server-rendered login** example using Flask sessions via Flask-Login. It assumes your `User` model already has `id`, `username`, and `password_hash` fields.

### App setup and login routes

```python
import os

from flask import Flask, render_template, request, redirect, url_for, flash
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],
    SQLALCHEMY_DATABASE_URI=os.environ.get(
        "DATABASE_URL", "sqlite:///budget_tracker.db"
    ),
    SQLALCHEMY_TRACK_MODIFICATIONS=False,
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    # Enable only when HTTPS is active in production.
    SESSION_COOKIE_SECURE=os.environ.get("FLASK_ENV") == "production",
)

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = "login"


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)


@login_manager.user_loader
def load_user(user_id):
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        if not username or not password:
            flash("Enter your username and password.", "warning")
            return render_template("login.html"), 400

        user = User.query.filter_by(username=username).first()
        if user is None or not user.check_password(password):
            # Use the same message for either failure to avoid revealing
            # whether a username exists.
            flash("Invalid username or password.", "danger")
            return render_template("login.html"), 401

        # Do not trust a user-supplied `next` URL without validating it.
        login_user(user, remember=False, fresh=True)
        return redirect(url_for("dashboard"))

    return render_template("login.html")


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


@app.route("/dashboard")
@login_required
def dashboard():
    return render_template("dashboard.html", user=current_user)


if __name__ == "__main__":
    app.run(port=5000, debug=True)
```

### `templates/login.html`

```html
<form method="post" action="{{ url_for('login') }}">
  <label for="username">Username</label>
  <input id="username" name="username" type="text" autocomplete="username" required>

  <label for="password">Password</label>
  <input id="password" name="password" type="password"
         autocomplete="current-password" required>

  <button type="submit">Log in</button>
</form>

{% with messages = get_flashed_messages(with_categories=true) %}
  {% for category, message in messages %}
    <p class="{{ category }}" role="alert">{{ message }}</p>
  {% endfor %}
{% endwith %}
```

Install/version-pin the relevant Python packages if needed: **Flask 2.3.1**, **Flask-Login 0.6.2**, **Flask-SQLAlchemy 3.0.3**, and **Werkzeug 2.3.1**. Bootstrap can style the template, but isn’t required for the login logic.

**Security notes:** Set `SECRET_KEY` to a strong secret in your deployment environment—don’t use a fallback secret in production. Add CSRF protection for form submissions (for example, Flask-WTF **1.1.1**) and rate-limit login attempts. Use HTTPS in production so secure cookies are sent only over TLS. If your existing database stores Argon2 hashes, keep using the matching Argon2 verifier; Werkzeug’s `check_password_hash` cannot verify Argon2 hashes.
